using System;using System.Data;using System.Data.SqlClient;using System.Text;using System.Web;namespace schoolms{public partial class student_Exams:System.Web.UI.Page{protected void Page_Load(object s,EventArgs e){string enrl=Session["Stud"] as string;if(enrl==null){Response.Redirect("Student_Login.aspx");return;}if(!IsPostBack)Load(enrl);}void Load(string enrl){try{using(SqlConnection c=Db.CreateConnection())using(SqlCommand q=new SqlCommand("SELECT ExamName,Subject,ExamDate,Marks,MaxMarks FROM StudentExams WHERE EnrlNo=@E ORDER BY ExamDate",c)){q.Parameters.Add("@E",SqlDbType.NVarChar,30).Value=enrl;c.Open();using(SqlDataReader r=q.ExecuteReader()){StringBuilder b=new StringBuilder("<table><tr><th>Exam</th><th>Subject</th><th>Date</th><th>Marks</th></tr>");while(r.Read())b.Append("<tr><td>").Append(HttpUtility.HtmlEncode(r.GetString(0))).Append("</td><td>").Append(HttpUtility.HtmlEncode(r.GetString(1))).Append("</td><td>").Append(r.GetDateTime(2).ToString("dd MMM yyyy")).Append("</td><td>").Append(r.IsDBNull(3)?"-":r.GetDecimal(3).ToString("N0")).Append(" / ").Append(r.GetDecimal(4).ToString("N0")).Append("</td></tr>");b.Append("</table>");litExams.Text=b.ToString();}}}catch(SqlException){litExams.Text="<p>Could not load exam details.</p>";}}}}
